// 获取上一个节点 (Extract from File) 的输入数据
const markdownContent = $node["Extract from File"].json.data;

// --- 配置部分 ---
const AUTHOR = "huangzuomin";
const PARENT_PERMLINK = "cn";
const DEFAULT_TAGS = ["n8n", "steemit", "ai"];

// --- 提取逻辑 ---
let title = "Untitled Article";
let tags = [...DEFAULT_TAGS];
let imageUrls = [];
let bodyContent = markdownContent;
let frontMatter = {};

// 简单的 YAML Front Matter 解析（无需外部库）
const frontMatterDelimiter = '---';
const lines = markdownContent.split('\n');

if (lines[0].trim() === frontMatterDelimiter) {
    let inFrontMatter = true;
    let frontMatterLines = [];
    let bodyStartIndex = 1;

    for (let i = 1; i < lines.length; i++) {
        if (lines[i].trim() === frontMatterDelimiter) {
            inFrontMatter = false;
            bodyStartIndex = i + 1;
            break;
        }
        frontMatterLines.push(lines[i]);
    }

    if (!inFrontMatter) {
        // 简单解析 YAML（支持基本的 key: value 和数组格式）
        const yamlString = frontMatterLines.join('\n');
        try {
            frontMatter = parseSimpleYaml(yamlString);
        } catch (e) {
            console.error("Error parsing YAML Front Matter:", e);
        }
        bodyContent = lines.slice(bodyStartIndex).join('\n').trim();
    } else {
        bodyContent = markdownContent;
    }
} else {
    bodyContent = markdownContent;
}

/**
 * 简单的 YAML 解析函数，支持基本的键值对和数组格式
 * @param {string} yamlString - 要解析的YAML字符串
 * @returns {object} 解析后的对象
 */
function parseSimpleYaml(yamlString) {
    const result = {};
    const lines = yamlString.split('\n');
    let currentKey = null;
    let currentArray = null;

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const trimmedLine = line.trim();

        // 跳过空行和注释
        if (!trimmedLine || trimmedLine.startsWith('#')) {
            continue;
        }

        // 检查是否是数组项（以 - 开头）
        if (trimmedLine.startsWith('- ')) {
            if (currentArray && currentKey) {
                let value = trimmedLine.substring(2).trim();
                // 移除引号
                if ((value.startsWith('"') && value.endsWith('"')) || 
                    (value.startsWith("'") && value.endsWith("'"))) {
                    value = value.slice(1, -1);
                }
                currentArray.push(value);
            }
            continue;
        }

        // 检查是否是键值对
        const colonIndex = trimmedLine.indexOf(':');
        if (colonIndex === -1) continue;

        const key = trimmedLine.substring(0, colonIndex).trim();
        let value = trimmedLine.substring(colonIndex + 1).trim();

        // 如果值为空，可能是数组的开始
        if (!value) {
            currentKey = key;
            currentArray = [];
            result[key] = currentArray;
            continue;
        }

        // 重置数组状态
        currentKey = null;
        currentArray = null;

        // 移除引号
        if ((value.startsWith('"') && value.endsWith('"')) || 
            (value.startsWith("'") && value.endsWith("'"))) {
            value = value.slice(1, -1);
        }

        // 处理方括号格式的数组
        if (value.startsWith('[') && value.endsWith(']')) {
            const arrayContent = value.slice(1, -1);
            if (arrayContent.trim()) {
                result[key] = arrayContent.split(',').map(item => {
                    let trimmed = item.trim();
                    if ((trimmed.startsWith('"') && trimmed.endsWith('"')) || 
                        (trimmed.startsWith("'") && trimmed.endsWith("'"))) {
                        trimmed = trimmed.slice(1, -1);
                    }
                    return trimmed;
                });
            } else {
                result[key] = [];
            }
        } else {
            result[key] = value;
        }
    }

    return result;
}

// 其余代码保持不变...
if (frontMatter.title) {
    title = frontMatter.title;
}

if (frontMatter.tags) {
    let extractedTags = [];
    if (Array.isArray(frontMatter.tags)) {
        extractedTags = frontMatter.tags.map(tag => String(tag).toLowerCase());
    } else if (typeof frontMatter.tags === 'string') {
        extractedTags = frontMatter.tags.split(',').map(tag => tag.trim().toLowerCase());
    }
    // 使用提取的标签替换默认标签，而不是合并
    tags = extractedTags.length > 0 ? extractedTags : DEFAULT_TAGS;
}

if (frontMatter.featured_image) {
    imageUrls = [frontMatter.featured_image];
}

const finalParentPermlink = tags.length > 0 ? tags[0] : PARENT_PERMLINK;

let permlink = title
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/^-+|-+$/g, '');

permlink = permlink + '-' + Date.now().toString(36).substring(0, 5);

const jsonMetadata = {
    tags: tags,
    app: "n8n-steemit-publisher/1.0.0",
    format: "markdown+html"
};

if (imageUrls.length > 0) {
    jsonMetadata.image = imageUrls;
}

if (frontMatter.summary) {
    jsonMetadata.description = frontMatter.summary;
}
if (frontMatter.date) {
    jsonMetadata.date = frontMatter.date;
}
if (frontMatter.main_topics) {
    jsonMetadata.main_topics = frontMatter.main_topics;
}

const outputData = {
    author: AUTHOR,
    permlink: permlink,
    parent_permlink: finalParentPermlink,
    title: title,
    body: bodyContent,
    tags: tags,
    json_metadata: JSON.stringify(jsonMetadata)
};

return [{ json: outputData }];
